CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "RoleName" AS ENUM ('USER','ADMIN');
CREATE TYPE "Plan" AS ENUM ('FREE','PREMIUM');
CREATE TYPE "SubscriptionStatus" AS ENUM ('ACTIVE','CANCELED','EXPIRED');
CREATE TYPE "ProviderName" AS ENUM ('OPENAI','ANTHROPIC','GOOGLE');
CREATE TABLE "Role" ("id" SERIAL PRIMARY KEY,"name" "RoleName" NOT NULL UNIQUE);
CREATE TABLE "User" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"name" TEXT,"isEmailVerified" BOOLEAN NOT NULL DEFAULT false,"roleId" INTEGER NOT NULL REFERENCES "Role"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"refreshTokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Subscription" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"plan" "Plan" NOT NULL DEFAULT 'FREE',"status" "SubscriptionStatus" NOT NULL DEFAULT 'ACTIVE',"requestLimit" INTEGER NOT NULL DEFAULT 50,"usedRequests" INTEGER NOT NULL DEFAULT 0,"startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endsAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AIProvider" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"name" "ProviderName" NOT NULL,"model" TEXT NOT NULL,"encryptedApiKey" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"isDefault" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Conversation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"title" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ChatMessage" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"conversationId" UUID NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE,"role" TEXT NOT NULL,"content" TEXT NOT NULL,"provider" "ProviderName","model" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WebSearch" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"query" TEXT NOT NULL,"results" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ApiUsageLog" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID REFERENCES "User"("id") ON DELETE SET NULL,"endpoint" TEXT NOT NULL,"method" TEXT NOT NULL,"provider" "ProviderName","model" TEXT,"statusCode" INTEGER NOT NULL,"latencyMs" INTEGER NOT NULL,"tokens" INTEGER NOT NULL DEFAULT 0,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AIProvider_userId_name_key" ON "AIProvider"("userId","name");
CREATE INDEX "Session_userId_revokedAt_idx" ON "Session"("userId","revokedAt");
CREATE INDEX "Subscription_userId_status_idx" ON "Subscription"("userId","status");
CREATE INDEX "AIProvider_userId_enabled_idx" ON "AIProvider"("userId","enabled");
CREATE INDEX "Conversation_userId_updatedAt_idx" ON "Conversation"("userId","updatedAt");
CREATE INDEX "ChatMessage_conversationId_createdAt_idx" ON "ChatMessage"("conversationId","createdAt");
CREATE INDEX "WebSearch_userId_createdAt_idx" ON "WebSearch"("userId","createdAt");
CREATE INDEX "ApiUsageLog_createdAt_idx" ON "ApiUsageLog"("createdAt");
CREATE INDEX "ApiUsageLog_userId_createdAt_idx" ON "ApiUsageLog"("userId","createdAt");
INSERT INTO "Role"("name") VALUES ('USER'),('ADMIN');
